// 📁 src/app/pages/booking/booking.module.ts

import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormsModule } from '@angular/forms';

import { BookingRoutingModule } from './booking-routing.module';
import { BookingComponent } from './booking.component';

// Importar servicios
import { BookingService } from '../../core/services/booking.service';

// Componentes auxiliares que vamos a crear
import { CalendarComponent } from './components/calendar/calendar.component';
import { PriceCalculatorComponent } from './components/price-calculator/price-calculator.component';
import { GuestSelectorComponent } from './components/guest-selector/guest-selector.component';
import { BookingConfirmationComponent } from './booking-confirmation/booking-confirmation.component';

@NgModule({
  declarations: [
    BookingComponent,
    CalendarComponent,
    PriceCalculatorComponent,
    GuestSelectorComponent,
    BookingConfirmationComponent
  ],
  imports: [
    CommonModule,
    ReactiveFormsModule,
    FormsModule,
    BookingRoutingModule
  ],
  providers: [
    BookingService
  ]
})
export class BookingModule { }
